<template>
  <div class="page">
    <div class="user-manage__table-wrap">
      <div class="panel">
        <div class="panel__header">
          <div class="panel__title">
            <h3>用户管理</h3>
          </div>
          <div class="panel__actions">
            <el-button type="primary" size="small" @click="openAddDialog">新增用户</el-button>
          </div>
        </div>
        <div class="panel__table-wrap">
          <el-table ref="tableRef" row-key="date" :data="pagedData" style="width: 100%" :header-cell-style="{ textAlign: 'left' }" :cell-style="{ textAlign: 'left' }">
            <el-table-column prop="id" label="用户ID" min-width="120" />
            <el-table-column prop="username" label="用户" min-width="120" />
            <el-table-column prop="nickname" label="昵称" min-width="120" />
            <el-table-column prop="level" label="等级" min-width="90" />
            <el-table-column prop="totalprice" label="累计消费" min-width="120" />
            <el-table-column prop="goodnum" label="订单数" min-width="90" />
            <el-table-column prop="role" label="角色" min-width="100">
              <template #default="scope">
                {{ roleName(scope.row.role) }}
              </template>
            </el-table-column>
            <el-table-column prop="status" label="状态" min-width="90">
              <template #default="scope">
                <el-tag :type="scope.row.status === 1 ? 'success' : 'danger'" disable-transitions>
                  {{ scope.row.status === 1 ? '正常' : '封禁' }}
                </el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="lastLoginTime" label="最后登录时间" min-width="170" />
            <el-table-column prop="createTime" label="创建时间" min-width="170" />
            <el-table-column label="操作" min-width="140">
              <template #default="scope">
                <el-button size="small" type="primary" link @click="openEditDialog(scope.row)">编辑</el-button>
                <el-button size="small" type="danger" link @click="handleDelete(scope.row)">删除</el-button>
              </template>
            </el-table-column>
          </el-table>
        </div>
      </div>
      <div class="user-manage__pagination-wrap">
        <div class="peoplenum">
          <h3>总人数统计</h3>
          <p>当前共 {{ tableData.length }} 人</p>
        </div>
        <div class="example-pagination-block">
          <el-pagination
            layout="prev, pager, next"
            :total="tableData.length"
            :page-size="pageSize"
            :current-page="currentPage"
            @current-change="currentPage = $event"
          />
        </div>
      </div>

      <el-dialog v-model="dialogVisible" :title="dialogTitle" width="480px">
        <el-form ref="addFormRef" :model="addForm" :rules="addFormRules" label-width="90px">
          <el-form-item label="用户名" prop="username">
            <el-input v-model="addForm.username" placeholder="请输入用户名" />
          </el-form-item>
          <el-form-item label="密码" prop="password">
            <el-input
              v-model="addForm.password"
              type="password"
              show-password
              :placeholder="dialogMode === 'edit' ? '留空则不修改密码' : '请输入密码'"
            />
          </el-form-item>
          <el-form-item label="昵称" prop="nickname">
            <el-input v-model="addForm.nickname" placeholder="请输入昵称" />
          </el-form-item>
          <el-form-item label="角色" prop="role">
            <el-select v-model="addForm.role" style="width: 100%">
              <el-option label="普通用户" :value="1" />
              <el-option label="客服" :value="2" />
              <el-option label="运营" :value="3" />
              <el-option label="审核" :value="4" />
              <el-option label="超级管理员" :value="9" />
            </el-select>
          </el-form-item>
          <el-form-item label="状态" prop="status">
            <el-select v-model="addForm.status" style="width: 100%">
              <el-option label="正常" :value="1" />
              <el-option label="封禁" :value="0" />
            </el-select>
          </el-form-item>
        </el-form>
        <template #footer>
          <el-button @click="dialogVisible = false">取消</el-button>
          <el-button type="primary" @click="handleSubmit">确 定</el-button>
        </template>
      </el-dialog>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, reactive, onMounted, getCurrentInstance } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
const { proxy } = getCurrentInstance()

// 分页状态
const currentPage = ref(1)
const pageSize = ref(6)
// 当前页展示的数据
const pagedData = computed(() => {
  const start = (currentPage.value - 1) * pageSize.value
  return tableData.value.slice(start, start + pageSize.value)
})

// 新增/编辑用户(users 表)
const dialogVisible = ref(false)
const dialogMode = ref('add') // add | edit
const editIndex = ref(-1)
const dialogTitle = computed(() => (dialogMode.value === 'add' ? '新增用户' : '编辑用户'))
const addFormRef = ref()
const addForm = reactive({
  username: '',
  password: '',
  nickname: '',
  role: 1,
  status: 1,
})
const addFormRules = {
  username: [{ required: true, message: '请输入用户名', trigger: 'blur' }],
  password: [{ required: true, message: '请输入密码', trigger: 'blur' }],
}
// 新增用户
const openAddDialog = () => {
  dialogMode.value = 'add'
  addForm.username = ''
  addForm.password = ''
  addForm.nickname = ''
  addForm.role = 1
  addForm.status = 1
  dialogVisible.value = true
}
// 编辑用户
const openEditDialog = (row) => {
  dialogMode.value = 'edit'
  editIndex.value = tableData.value.indexOf(row)
  addForm.username = row.username
  addForm.password = ''
  addForm.nickname = row.nickname || ''
  addForm.role = row.role
  addForm.status = row.status
  dialogVisible.value = true
}
// 提交表单
const handleSubmit = () => {
  addFormRef.value.validate((valid) => {
    if (!valid) return
    if (dialogMode.value === 'add') {
      const submitItem = {
        username: addForm.username,
        password: addForm.password,
        nickname: addForm.nickname,
        role: addForm.role,
        status: addForm.status,
      }
      proxy.$request.post('/api/users', submitItem).then((res) => {
        if (res.code === 1) {
          currentPage.value = 1
          ElMessage.success(`用户「${addForm.username}」已新增`)
          getuserlist()
        } else {
          ElMessage.error(res.message || '新增用户失败')
        }
      })
    } else {
      const row = tableData.value[editIndex.value]
      const submitItem = {
        username: addForm.username,
        nickname: addForm.nickname,
        role: addForm.role,
        status: addForm.status,
        password: addForm.password,
      }
      // 编辑时填了密码才更新密码
      if (addForm.password) submitItem.password = addForm.password
      proxy.$request.put(`/api/users/${row.id}`, submitItem).then((res) => {
        if (res.code === 1) {
          ElMessage.success(`用户「${addForm.username}」已更新`)
          getuserlist()
        } else {
          ElMessage.error(res.message || '更新用户失败')
        }
      })
    }
    dialogVisible.value = false
  })
}
// 删除用户
const handleDelete = (row) => {
  ElMessageBox.confirm(`确定删除用户「${row.username}」吗？`, '提示', { type: 'warning' })
    .then(() => {
      proxy.$request.delete(`/api/users/${row.id}`).then((res) => {
        if (res.code === 1) {
          ElMessage.success(`用户「${row.username}」已删除`)
          getuserlist()
        } else {
          ElMessage.error(res.message || '删除用户失败')
        }
      })
    })
    .catch(() => {}) // 取消删除
}
// 角色对应的中文名
const roleName = (role) => {
  const map = {
    1: '普通用户',
    2: '客服',
    3: '运营',
    4: '审核',
    9: '超级管理员',
  }
  return map[role] || role
}
// 表格数据
const tableData = ref([])
// 调用获取用户列表接口
const getuserlist = () => {
  proxy.$request({
    url: '/api/users',
    method: 'get',
  }).then((res) => {
    if (res.code === 1) {
      tableData.value = res.data || []
    }
  }).catch(() => {
    ElMessage.error('获取用户列表失败')
  })
}
onMounted(() => {
  getuserlist()
})
</script>

