/* 大盒子 */
.user-manage__table-wrap{
  background-color: #ffffff;
  margin: 12px;
  border-radius: 8px;
  min-width: 0;
  overflow-x: auto;
}
/* 面板 */
.panel {
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
